var opacity = 11;
let timer=0
function setup() 
{
  createCanvas(windowWidth, windowHeight)
  background(0);
}

function draw() 
{
	timer++
	if(timer<=100)
	{
	   stroke(random(255),random(255),random(255));
		strokeWeight(2)
	   translate(400,height);
	   var angle = random(0,6.14);
	   branch(281,angle);
		branch(81,angle);
	   translate(0,height-370)
	   branch(500,angle);
	}
}


function branch(len,theta) 
{
  strokeWeight(random(5))
  translate(random(width/43),0)
  line(0,0,0,-len);
  translate(0,-len);
  var a = random(10.0);
  if(len>2)
  {
    push();
      rotate(theta);
      branch(random(.5)*len,theta);
    pop();
    push();
      rotate(-theta);
      branch(0.618*len,theta);
    pop();  
  }
}

